fn record(cp: u21) TerminalProperties {
    if (cp > 0x10ffff) return @bitCast(@as(u12, 0x280));
    const block = index[cp >> block_shift];
    return @bitCast(@as(u12, @truncate(data[(@as(usize, block) << block_shift) | (cp & ((1 << block_shift) - 1))])));
}
pub fn terminalProperties(cp: u21) TerminalProperties { return record(cp); }
pub fn eastAsianWidth(cp: u21) EastAsianWidth { return record(cp).east_asian_width; }
pub fn isEmojiPresentation(cp: u21) bool { return record(cp).emoji_presentation; }
pub fn isEmojiVariationBase(cp: u21) bool { return record(cp).emoji_variation_base; }
pub fn isEmojiModifier(cp: u21) bool { return record(cp).emoji_modifier; }
pub fn isEmojiModifierBase(cp: u21) bool { return record(cp).emoji_modifier_base; }
pub fn isEmoji(cp: u21) bool { return record(cp).emoji; }
pub fn isEmojiComponent(cp: u21) bool { return record(cp).emoji_component; }
pub fn widthProperties(cp: u21) WidthProperties { const r = record(cp); return .{ .standalone = r.standalone, .zero_in_grapheme = r.zero_in_grapheme, .emoji_modifier = r.emoji_modifier }; }
